                    <h5 class="modal-title">@(editingShipment.Id == 0 ? "New Shipment" : "Edit Shipment")</h5>
                    <button type="button" class="btn-close" @onclick="CloseForm"></button>
                </div>
                <div class="modal-body">
                    @if (formError is not null)
                    {
                        <div class="alert alert-danger">@formError</div>
                    }
                    <EditForm Model="editingShipment" OnValidSubmit="SaveShipment" FormName="shipmentForm">
                        <DataAnnotationsValidator />
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Tracking Number</label>
                                <InputText class="form-control" @bind-Value="editingShipment.TrackingNumber"
                                           disabled="@(editingShipment.Id != 0)" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Status</label>
                                <InputSelect class="form-select" @bind-Value="editingShipment.Status">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </InputSelect>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Description" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Origin</label>
                                <InputText class="form-control" @bind-Value="editingShipment.Origin" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Destination</label>
                                <InputText class="form-control" @bind-Value="editingShipment.Destination" />
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Estimated Delivery</label>
                                <InputDate class="form-control" @bind-Value="editingShipment.EstimatedDelivery" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Customer Email</label>
                                <InputText class="form-control" @bind-Value="editingShipment.CustomerEmail" />
                            </div>
                        </div>
                        <div class="d-flex justify-content-end gap-2">
                            <button type="button" class="btn btn-secondary" @onclick="CloseForm">Cancel</button>
                            <button type="submit" class="btn btn-primary" disabled="@isSaving">
                                @if (isSaving)
                                {
                                    <span class="spinner-border spinner-border-sm me-1"></span>
                                }
                                Save
                            </button>
                        </div>
                    </EditForm>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private string? errorMessage;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;

    private bool showForm;
    private bool isSaving;
    private string? formError;
    private Shipment editingShipment = new();

    private List<Shipment> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
        .Where(s => string.IsNullOrEmpty(searchTerm)
            || s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
            || s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
            || s.CustomerEmail.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            errorMessage = "Failed to load shipments.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm()
    {
        editingShipment = new Shipment
        {
            TrackingNumber = $"SHP-{Random.Shared.Next(1000, 9999)}"
        };
        formError = null;
        showForm = true;
    }

    private void EditShipment(Shipment shipment)
    {
        editingShipment = new Shipment
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Description = shipment.Description,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail
        };
        formError = null;
        showForm = true;
    }

    private void CloseForm() => showForm = false;

    private async Task SaveShipment()
    {
        isSaving = true;
        formError = null;
        try
        {
            if (editingShipment.Id == 0)
                await ShipmentService.CreateShipmentAsync(editingShipment);
            else
                await ShipmentService.UpdateShipmentAsync(editingShipment);

            showForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            formError = $"Failed to save shipment: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task DeleteShipment(int id)
    {
        try
        {
            await ShipmentService.DeleteShipmentAsync(id);
            await LoadShipments();
        }
        catch
        {
            errorMessage = "Failed to delete shipment.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-secondary"
    };
}
