﻿@page "/"

<PageTitle>Track Shipment - ShipmentTracker</PageTitle>

<div class="container">
    <h1>Track Your Shipment</h1>
    <p class="lead">Enter your tracking number to check the status and estimated delivery of your shipment.</p>

    <div class="row mb-4">
        <div class="col-md-8">
            <div class="input-group">
                <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g., SHP-001)"
                       @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-warning">@errorMessage</div>
    }

    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Estimated Delivery</dt>
                            <dd>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    @shipment.EstimatedDelivery.Value.ToString("dddd, MMMM d, yyyy")
                                }
                                else
                                {
                                    <span class="text-muted">Not yet determined</span>
                                }
                            </dd>
                            <dt>Last Updated</dt>
                            <dd>@shipment.UpdatedAt.ToString("g")</dd>
                        </dl>
                    </div>
                </div>

                <h6>Shipment Progress</h6>
                <div class="progress mb-2" style="height: 24px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)" role="progressbar"
                         style="width: @GetProgressPercent(shipment.Status)%">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (shipment is null)
                errorMessage = $"No shipment found with tracking number \"{trackingNumber.Trim()}\".";
        }
        catch
        {
            errorMessage = "Unable to retrieve shipment information. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.OutForDelivery => "bg-warning",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        _ => 0
    };
}

